alter table public.trips add column if not exists updated_at timestamptz not null default now();
create table if not exists public.trip_history(id uuid primary key default gen_random_uuid(),trip_id uuid not null references public.trips(id) on delete cascade,municipality_id uuid not null references public.municipalities(id),user_id uuid references public.profiles(id),action text not null check(action in ('CREATED','UPDATED','STATUS_CHANGED')),old_status public.trip_status,new_status public.trip_status,old_data jsonb,new_data jsonb,note text,changed_at timestamptz not null default now());
alter table public.trip_history enable row level security; revoke all on table public.trip_history from anon,authenticated; grant select on table public.trip_history to authenticated;
drop policy if exists "trip_history_select_same_municipality" on public.trip_history; create policy "trip_history_select_same_municipality" on public.trip_history for select to authenticated using ((select private.current_user_role())='ADMIN'::public.user_role or municipality_id=(select private.current_user_municipality_id()));
create index if not exists trip_history_trip_idx on public.trip_history(trip_id,changed_at desc); create index if not exists trip_history_municipality_idx on public.trip_history(municipality_id,changed_at desc); create index if not exists trip_passengers_request_idx on public.trip_passengers(request_id);
create or replace function private.touch_trip_updated_at() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end;$$; drop trigger if exists trips_touch_updated_at on public.trips; create trigger trips_touch_updated_at before update on public.trips for each row execute function private.touch_trip_updated_at();
create or replace function private.validate_trip_change() returns trigger language plpgsql security invoker set search_path='' as $$begin if tg_op='UPDATE' and new.status is distinct from old.status and not ((old.status='SCHEDULED' and new.status in ('IN_PROGRESS','CANCELLED')) or (old.status='IN_PROGRESS' and new.status in ('COMPLETED','CANCELLED'))) then raise exception 'Transição de viagem inválida: % -> %',old.status,new.status; end if; if new.status='CANCELLED' and nullif(btrim(new.cancellation_reason),'') is null then raise exception 'Informe o motivo do cancelamento da viagem.'; end if; if new.status='COMPLETED' and (new.final_mileage is null or new.initial_mileage is null) then raise exception 'Informe KM inicial e final antes de concluir.'; end if; if new.final_mileage is not null and new.initial_mileage is not null and new.final_mileage<new.initial_mileage then raise exception 'KM final não pode ser menor que KM inicial.'; end if; if new.status='IN_PROGRESS' and new.started_at is null then new.started_at:=now(); end if; if new.status='COMPLETED' and new.completed_at is null then new.completed_at:=now(); end if; if new.status='CANCELLED' and new.cancelled_at is null then new.cancelled_at:=now(); end if; return new;end;$$;
drop trigger if exists trips_validate_change on public.trips; create trigger trips_validate_change before update on public.trips for each row execute function private.validate_trip_change();
create or replace function private.record_trip_history() returns trigger language plpgsql security definer set search_path='' as $$declare a text;n text;begin if tg_op='INSERT' then a:='CREATED';elsif new.status is distinct from old.status then a:='STATUS_CHANGED';else a:='UPDATED';end if;if new.status='CANCELLED' then n:=new.cancellation_reason;end if;insert into public.trip_history(trip_id,municipality_id,user_id,action,old_status,new_status,old_data,new_data,note) values(new.id,new.municipality_id,(select auth.uid()),a,case when tg_op='UPDATE' then old.status end,new.status,case when tg_op='UPDATE' then to_jsonb(old) end,to_jsonb(new),n);return new;end;$$; revoke all on function private.record_trip_history() from public; grant execute on function private.record_trip_history() to authenticated; drop trigger if exists trips_record_history on public.trips; create trigger trips_record_history after insert or update on public.trips for each row execute function private.record_trip_history();